import type { Page } from '../types';

/**
 * A plugin module from `./plugins/` or the `ssg.config.ts` file can either
 * export a ready-made `Plugin` instance or a factory that receives the
 * shared context and returns one.
 */
export type PluginFactory = (context: PluginContext) => Plugin | Promise<Plugin>;

/**
 * The configuration file (`ssg.config.ts`) shape. Directory options can be
 * overridden by command-line flags; the `plugins` array lists plugin modules
 * under `./plugins/` (by name or path) or inline plugin factories.
 */
export interface SSGConfig {
  contentDir?: string;
  outputDir?: string;
  templateDir?: string;
  defaultTemplate?: string;
  defaultLayout?: string;
  plugins?: Array<string | Plugin | PluginFactory>;
  [key: string]: unknown;
}

/**
 * The lifecycle hooks a plugin may implement. Every hook in the pipeline is
 * invoked for each plugin in registration order.
 */
export interface Plugin {
  /** Unique name, used for diagnostics and ordering. */
  name: string;
  /** Runs once when the engine starts (before any build). */
  onStart?(context: PluginContext): void | Promise<void>;
  /** Runs before the site is built (prepare templates, directories, ...). */
  beforeBuild?(context: PluginContext): void | Promise<void>;
  /** Runs after every page has been produced (write output, ...). */
  afterBuild?(context: PluginContext): void | Promise<void>;
  /**
   * Runs for every file in the content directory. May return a page to
   * include it in the build, a modified page, or `undefined`/`null` to skip
   * the file entirely.
   */
  onFile?(page: Page, context: PluginContext): Page | undefined | null | void | Promise<Page | undefined | null | void>;
  /** Runs once when the engine finishes (cleanup, ...). */
  onEnd?(context: PluginContext): void | Promise<void>;
}

/**
 * Shared state handed to every plugin. The engine exposes the resolved
 * directories, the accumulated pages, and an `engine` reference so plugins
 * can trigger rebuilds (used by the dev-server plugin).
 */
export interface PluginContext {
  /** The command being run: `build` or `serve`. */
  command: 'build' | 'serve';
  /** The loaded configuration file (empty object when none is present). */
  config: SSGConfig;
  contentDir: string;
  outputDir: string;
  templateDir?: string;
  defaultTemplate?: string;
  defaultLayout?: string;
  /** Pages collected so far; populated by the engine. */
  pages: Page[];
  /** The plugins participating in this run, in order. */
  plugins: Plugin[];
  /** Arbitrary shared storage between plugins. */
  shared: Record<string, unknown>;
  /** The engine driving the pipeline. */
  engine: PluginEngine;
}

/** The subset of the engine plugins can drive. */
export interface PluginEngine {
  build(): Promise<Page[]>;
  buildSync(): Page[];
}

import { escapeHtml } from './escape';
import type { Page } from './types';

/**
 * Built-in rendering used when no template engine is configured. Mirrors the
 * historical output of the generator so templated and non-templated sites
 * stay consistent.
 */
export function renderPage(page: Page): string {
  const date = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';
  const tags = page.tags
    ? `<ul class="tags">${page.tags
        .map((tag) => `<li>${escapeHtml(tag)}</li>`)
        .join('')}</ul>`
    : '';
  return [
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    `<title>${escapeHtml(page.title)}</title>`,
    '</head>',
    '<body>',
    '<header>',
    `<h1>${escapeHtml(page.title)}</h1>`,
    date,
    tags,
    '</header>',
    '<main>',
    page.contentHtml,
    '</main>',
    '</body>',
    '</html>',
    '',
  ].join('\n');
}

export function sortPages(pages: Page[]): Page[] {
  return [...pages].sort((a, b) => {
    if (a.date && b.date) {
      return b.date.localeCompare(a.date);
    }
    if (a.date) return -1;
    if (b.date) return 1;
    return a.slug.localeCompare(b.slug);
  });
}

export function renderIndex(pages: Page[]): string {
  const items = sortPages(pages)
    .map((page) => {
      const date = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
      return `    <li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(
        page.title
      )}</a>${date}</li>`;
    })
    .join('\n');
  return [
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    '<title>Index</title>',
    '</head>',
    '<body>',
    '<h1>Index</h1>',
    '<ul>',
    items,
    '</ul>',
    '</body>',
    '</html>',
    '',
  ].join('\n');
}

import fs from 'fs';
import path from 'path';
import { renderMarkdownToHtml } from '../markdown';
import type { Page } from '../types';
import type { Plugin, PluginContext } from './types';

const MARKDOWN_EXTENSIONS = /\.(md|markdown)$/;

function pageTitle(data: Record<string, unknown>, slug: string): string {
  const title = data.title;
  return typeof title === 'string' && title.trim().length > 0 ? title : slug;
}

function pageDate(data: Record<string, unknown>): string | undefined {
  const date = data.date;
  return typeof date === 'string' && date.length > 0 ? date : undefined;
}

function pageTags(data: Record<string, unknown>): string[] | undefined {
  if (!Array.isArray(data.tags)) {
    return undefined;
  }
  const tags = data.tags.map(String).filter((tag) => tag.trim().length > 0);
  return tags.length > 0 ? tags : undefined;
}

function pageStringField(data: Record<string, unknown>, key: string): string | undefined {
  const value = data[key];
  return typeof value === 'string' && value.trim().length > 0 ? value : undefined;
}

/**
 * Built-in markdown plugin: reads `*.md` / `*.markdown` files from the
 * content directory, renders them to HTML and exposes the frontmatter as
 * page metadata. Files with any other extension are skipped.
 */
export class MarkdownPlugin implements Plugin {
  readonly name = 'markdown';

  onFile(page: Page, context: PluginContext): Page | undefined {
    const fileName = page.slug;
    if (!MARKDOWN_EXTENSIONS.test(fileName)) {
      return undefined;
    }
    const raw = fs.readFileSync(path.join(context.contentDir, fileName), 'utf8');
    const slug = fileName.replace(MARKDOWN_EXTENSIONS, '');
    const { data, content, html } = renderMarkdownToHtml(raw);
    return {
      slug,
      title: pageTitle(data, slug),
      date: pageDate(data),
      tags: pageTags(data),
      template: pageStringField(data, 'template'),
      layout: pageStringField(data, 'layout'),
      data,
      contentHtml: html,
      content,
    };
  }
}

import fs from 'fs';
import path from 'path';
import { TemplateEngine } from '../templates';
import { renderIndex, renderPage } from '../render';
import type { Plugin, PluginContext } from './types';

/**
 * Resolve the template directory. An explicitly requested directory that does
 * not exist is an error; the default `./templates` directory is only used when
 * present so sites without templates keep the built-in rendering.
 */
export function resolveTemplateDir(
  templateDir: string | undefined
): string | null {
  if (templateDir !== undefined) {
    const dir = path.resolve(templateDir);
    if (!fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) {
      throw new Error(`Template directory does not exist: ${dir}`);
    }
    return dir;
  }
  const dir = path.resolve('templates');
  return fs.existsSync(dir) && fs.statSync(dir).isDirectory() ? dir : null;
}

/**
 * Built-in template plugin: renders every collected page (and the site index)
 * through Handlebars templates, layouts and partials when a template
 * directory is present, otherwise through the built-in rendering. Writes the
 * finished HTML files into the output directory.
 */
export class TemplatePlugin implements Plugin {
  readonly name = 'template';

  private engine: TemplateEngine | null = null;

  beforeBuild(context: PluginContext): void {
    const templateDir = resolveTemplateDir(context.templateDir);
    this.engine =
      templateDir === null
        ? null
        : new TemplateEngine({
            templateDir,
            defaultTemplate: context.defaultTemplate,
            defaultLayout: context.defaultLayout,
          });
  }

  afterBuild(context: PluginContext): void {
    const engine = this.engine;
    for (const page of context.pages) {
      const html =
        engine && engine.hasContent() ? engine.renderPage(page) : renderPage(page);
      fs.writeFileSync(path.join(context.outputDir, `${page.slug}.html`), html);
    }
    const indexHtml =
      engine && engine.hasContent() ? engine.renderIndex(context.pages) : renderIndex(context.pages);
    fs.writeFileSync(path.join(context.outputDir, 'index.html'), indexHtml);
  }

  /** Access to the underlying template engine (may be null). */
  getEngine(): TemplateEngine | null {
    return this.engine;
  }
}

import fs from 'fs';
import path from 'path';
import type { Page } from './types';
import type { Plugin, PluginContext, PluginEngine, SSGConfig } from './plugins/types';

export type EngineCommand = 'build' | 'serve';

export interface EngineOptions {
  contentDir: string;
  outputDir: string;
  templateDir?: string;
  defaultTemplate?: string;
  defaultLayout?: string;
  command?: EngineCommand;
  config?: SSGConfig;
}

type HookName = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd';

function isPromise(value: unknown): value is Promise<unknown> {
  return (
    value !== null &&
    typeof value === 'object' &&
    typeof (value as { then?: unknown }).then === 'function'
  );
}

/**
 * The core SSG engine. Owns the shared plugin context and orchestrates the
 * plugin pipeline. Hooks run in plugin registration order:
 *
 *   onStart -> beforeBuild -> onFile (per content file) -> afterBuild -> onEnd
 *
 * The pipeline is available both synchronously (`buildSync`/`runSync`) for
 * the CLI build command and asynchronously (`build`/`run`) so plugins can
 * perform async work in long-running sessions such as the dev server.
 */
export class SsgEngine implements PluginEngine {
  readonly plugins: Plugin[];
  readonly context: PluginContext;

  private readonly contentDir: string;
  private readonly outputDir: string;

  constructor(options: EngineOptions, plugins: Plugin[]) {
    this.plugins = plugins;
    this.contentDir = path.resolve(options.contentDir);
    this.outputDir = path.resolve(options.outputDir);
    const context: PluginContext = {
      command: options.command ?? 'build',
      config: options.config ?? {},
      contentDir: this.contentDir,
      outputDir: this.outputDir,
      templateDir: options.templateDir,
      defaultTemplate: options.defaultTemplate,
      defaultLayout: options.defaultLayout,
      pages: [],
      plugins,
      shared: {},
      engine: this,
    };
    this.context = context;
  }

  /** Run the `onStart` hooks. */
  async start(): Promise<void> {
    await this.runHook('onStart');
  }

  /** Run the `onEnd` hooks. */
  async end(): Promise<void> {
    await this.runHook('onEnd');
  }

  /** Run the full build pipeline and return the generated pages. */
  async build(): Promise<Page[]> {
    this.validateContentDir();
    await this.runHook('beforeBuild');
    fs.mkdirSync(this.outputDir, { recursive: true });
    const pages = await this.collectPages();
    this.context.pages = pages;
    await this.runHook('afterBuild');
    return pages;
  }

  /** Run the entire lifecycle: onStart, build, onEnd. */
  async run(): Promise<Page[]> {
    await this.start();
    const pages = await this.build();
    await this.end();
    return pages;
  }

  /** Synchronous build pipeline (all hooks must return synchronously). */
  buildSync(): Page[] {
    this.validateContentDir();
    this.runHookSync('beforeBuild');
    fs.mkdirSync(this.outputDir, { recursive: true });
    const pages = this.collectPagesSync();
    this.context.pages = pages;
    this.runHookSync('afterBuild');
    return pages;
  }

  /** Synchronous full lifecycle: onStart, build, onEnd. */
  runSync(): Page[] {
    this.runHookSync('onStart');
    const pages = this.buildSync();
    this.runHookSync('onEnd');
    return pages;
  }

  private validateContentDir(): void {
    if (!fs.existsSync(this.contentDir)) {
      throw new Error(`Content directory does not exist: ${this.contentDir}`);
    }
    if (!fs.statSync(this.contentDir).isDirectory()) {
      throw new Error(`Content path is not a directory: ${this.contentDir}`);
    }
  }

  private async runHook(name: HookName): Promise<void> {
    for (const plugin of this.plugins) {
      const hook = plugin[name];
      if (!hook) {
        continue;
      }
      await hook(this.context);
    }
  }

  private runHookSync(name: HookName): void {
    for (const plugin of this.plugins) {
      const hook = plugin[name];
      if (!hook) {
        continue;
      }
      const result = hook(this.context);
      if (isPromise(result)) {
        throw new Error(
          `Plugin "${plugin.name}" returned a Promise from "${name}" during a synchronous build`
        );
      }
    }
  }

  private async collectPages(): Promise<Page[]> {
    const pages: Page[] = [];
    const entries = fs.readdirSync(this.contentDir).sort();
    for (const entry of entries) {
      const page = await this.runOnFile(entry);
      if (page) {
        pages.push(page);
      }
    }
    return pages;
  }

  private collectPagesSync(): Page[] {
    const pages: Page[] = [];
    const entries = fs.readdirSync(this.contentDir).sort();
    for (const entry of entries) {
      const page = this.runOnFileSync(entry);
      if (page) {
        pages.push(page);
      }
    }
    return pages;
  }

  private async runOnFile(entry: string): Promise<Page | null> {
    let page: Page | null | undefined = { slug: entry, title: entry, contentHtml: '', content: '' };
    for (const plugin of this.plugins) {
      if (!plugin.onFile) {
        continue;
      }
      const result = await plugin.onFile(page, this.context);
      if (result === undefined || result === null) {
        page = null;
        break;
      }
      page = result;
    }
    return page;
  }

  private runOnFileSync(entry: string): Page | null {
    let page: Page | null | undefined = { slug: entry, title: entry, contentHtml: '', content: '' };
    for (const plugin of this.plugins) {
      if (!plugin.onFile) {
        continue;
      }
      const result = plugin.onFile(page, this.context);
      if (isPromise(result)) {
        throw new Error(
          `Plugin "${plugin.name}" returned a Promise from "onFile" during a synchronous build`
        );
      }
      if (result === undefined || result === null) {
        page = null;
        break;
      }
      page = result;
    }
    return page;
  }
}

import type { AddressInfo } from 'net';
import { LiveReloadDevServer } from '../dev-server';
import type { DevServerOptions } from '../dev-server';
import type { Plugin, PluginContext, PluginEngine } from './types';

/**
 * Built-in dev-server plugin: runs the live-reload development server for the
 * `serve` command. It performs the initial build through the plugin pipeline
 * and re-runs that pipeline on every file change so the site is rebuilt the
 * same way as a plain `build`.
 */
export class DevServerPlugin implements Plugin {
  readonly name = 'dev-server';

  private server: LiveReloadDevServer | null = null;
  private context: PluginContext | null = null;

  onStart(context: PluginContext): void {
    this.context = context;
  }

  onEnd(context: PluginContext): void {
    this.context = context;
  }

  /** The running dev server, once `start` has completed. */
  getServer(): LiveReloadDevServer | null {
    return this.server;
  }

  /**
   * Start the dev server and wait until it is listening. Uses an ephemeral
   * port when `port` is 0. An initial build is performed through the engine
   * so the output directory is up to date before serving begins.
   */
  start(engine: PluginEngine, options: DevServerOptions): Promise<LiveReloadDevServer> {
    const rebuild = (): boolean => {
      try {
        engine.buildSync();
        return true;
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        console.error(`Rebuild failed: ${message}`);
        return false;
      }
    };

    const devServer = new LiveReloadDevServer({ ...options, rebuild });

    let initialBuildError: unknown;
    try {
      engine.buildSync();
    } catch (error) {
      initialBuildError = error;
    }

    if (initialBuildError !== undefined) {
      devServer.watcher.close().catch(() => undefined);
      return Promise.reject(initialBuildError);
    }

    return new Promise<LiveReloadDevServer>((resolve, reject) => {
      const listening = new Promise<void>((resolveListen, rejectListen) => {
        devServer.server.once('error', rejectListen);
        devServer.server.once('listening', () => {
          devServer.server.removeListener('error', rejectListen);
          const address = devServer.server.address() as AddressInfo | null;
          if (address && typeof address === 'object') {
            devServer.port = address.port;
          }
          resolveListen();
        });
        devServer.server.listen(devServer.port);
      });
      const watcherReady = new Promise<void>((resolveReady) => {
        devServer.watcher.once('ready', () => resolveReady());
      });

      Promise.all([listening, watcherReady])
        .then(() => {
          this.server = devServer;
          resolve(devServer);
        })
        .catch((error) => {
          devServer.watcher.close().catch(() => undefined);
          reject(error);
        });
    });
  }
}

import { MarkdownPlugin } from './markdown-plugin';
import { TemplatePlugin } from './template-plugin';
import { DevServerPlugin } from './dev-server-plugin';
import type { Plugin } from './types';

/**
 * The built-in plugin set. Markdown parsing and template rendering always
 * participate; the dev server plugin is only registered for the `serve`
 * command.
 */
export function defaultPlugins(command: 'build' | 'serve' = 'build'): Plugin[] {
  const plugins: Plugin[] = [new MarkdownPlugin(), new TemplatePlugin()];
  if (command === 'serve') {
    plugins.push(new DevServerPlugin());
  }
  return plugins;
}

import fs from 'fs';
import path from 'path';
import ts from 'typescript';
import type { Plugin, PluginFactory, SSGConfig } from './plugins/types';

type LoadedModule = { default?: unknown } | unknown;
type RequireExtensions = Record<string, (module: unknown, filename: string) => void>;
type TsModule = { _compile(code: string, filename: string): void };

/**
 * Register a CommonJS loader for `.ts` files so plugin modules and the
 * `ssg.config.ts` file can be `require`d at runtime without a build step.
 * Existing loaders (e.g. ts-jest) are left untouched.
 */
function registerTypeScriptLoader(): void {
  const extensions = (require as unknown as { extensions: RequireExtensions }).extensions;
  if (extensions['.ts']) {
    return;
  }
  extensions['.ts'] = (module, filename) => {
    const source = fs.readFileSync(filename, 'utf8');
    const { outputText } = ts.transpileModule(source, {
      fileName: filename,
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2020,
        esModuleInterop: true,
      },
    });
    (module as TsModule)._compile(outputText, filename);
  };
}

function loadModule(filePath: string): unknown {
  registerTypeScriptLoader();
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const loaded = require(filePath) as LoadedModule;
  const value = (loaded as { default?: unknown }).default ?? loaded;
  return value;
}

function fileCandidates(base: string): string[] {
  if (path.extname(base)) {
    return [base];
  }
  return [base, `${base}.ts`, `${base}.js`];
}

function findFile(candidates: string[]): string | null {
  return (
    candidates.find((candidate) => fs.existsSync(candidate) && fs.statSync(candidate).isFile()) ??
    null
  );
}

/**
 * Resolve the `ssg.config.ts` file. Uses `./ssg.config.ts` relative to
 * `rootDir` (the current working directory by default).
 */
export function loadConfig(configPath?: string, rootDir: string = process.cwd()): SSGConfig | null {
  const given = configPath ?? path.resolve(rootDir, 'ssg.config.ts');
  const resolved = findFile(fileCandidates(given));
  if (!resolved) {
    return null;
  }
  const value = loadModule(resolved);
  return value && typeof value === 'object' ? (value as SSGConfig) : null;
}

/**
 * Resolve a plugin entry. Strings are module names under `./plugins/`
 * (or explicit paths); the returned value is a `Plugin` instance or a
 * `PluginFactory` when the module exports a factory function.
 */
export function loadPluginModule(entry: string, rootDir: string = process.cwd()): Plugin | PluginFactory {
  let resolved: string;
  if (path.isAbsolute(entry)) {
    resolved = entry;
  } else if (entry.startsWith('.')) {
    resolved = path.resolve(rootDir, entry);
  } else {
    resolved = path.resolve(rootDir, 'plugins', entry);
  }
  const existing = findFile([
    resolved,
    ...fileCandidates(resolved),
    ...fileCandidates(path.join(resolved, 'index')),
  ]);
  if (!existing) {
    throw new Error(`Plugin module not found: ${entry}`);
  }
  const value = loadModule(existing);
  if (typeof value === 'function') {
    return value as PluginFactory;
  }
  return value as Plugin;
}

/**
 * Build the plugin list declared in a config file. String entries are loaded
 * from `./plugins/`; inline plugin instances and factories pass through.
 */
export function pluginsFromConfig(
  config: SSGConfig | null,
  rootDir: string = process.cwd()
): Array<Plugin | PluginFactory> {
  if (!config || !Array.isArray(config.plugins)) {
    return [];
  }
  return config.plugins.map((entry) => {
    if (typeof entry === 'string') {
      return loadPluginModule(entry, rootDir);
    }
    return entry;
  });
}

