import type { Plugin, PluginContext, Page } from 'ssg';

const events: string[] = [];

const plugin: Plugin = {
  name: 'hello',
  onStart(context: PluginContext): void {
    events.push('onStart');
  },
  beforeBuild(context: PluginContext): void {
    events.push('beforeBuild');
  },
  onFile(page: Page): Page | undefined {
    if (page.slug.endsWith('.md')) {
      return { ...page, title: `${page.title} [custom]` };
    }
    return page;
  },
  afterBuild(context: PluginContext): void {
    events.push(`afterBuild:${context.pages.length}`);
  },
  onEnd(context: PluginContext): void {
    events.push('onEnd');
  },
};

export default plugin;

import type { SSGConfig } from 'ssg';
import type { Plugin } from 'ssg';
import hello from './plugins/hello';

const config: SSGConfig = {
  contentDir: './content',
  outputDir: './dist',
  plugins: [hello, './plugins/hello'],
};

export default config;

import type { Plugin, PluginContext, Page } from 'ssg';

const events: string[] = [];

const plugin: Plugin = {
  name: 'hello',
  onStart(context: PluginContext): void {
    events.push('onStart');
  },
  beforeBuild(context: PluginContext): void {
    events.push('beforeBuild');
  },
  onFile(page: Page): Page {
    return { ...page, title: `${page.title} [custom]` };
  },
  afterBuild(context: PluginContext): void {
    events.push(`afterBuild:${context.pages.length}`);
  },
  onEnd(context: PluginContext): void {
    events.push('onEnd');
    // eslint-disable-next-line no-console
    console.log(`plugin-events: ${events.join(' -> ')}`);
  },
};

export default plugin;

